static u16 read16(const u8* memory, u32 address) {
    return static_cast<u16>(memory[address]) |
           (static_cast<u16>(memory[address + 1]) << 8);
}

static bool read_mode0_pixel(GameboyAdvanceHarness& gba, int x, int y, u16& out) {
    auto vram = gba.get_top().rootp->GameboyAdvance__DOT__ppu__DOT__VRAM__DOT__mem;
    auto palette = gba.get_top().rootp->GameboyAdvance__DOT__Palette__DOT__mem;
    u16 dispcnt = read16(&gba.read_memory(0x04000000), 0);

    // Palette entry zero is Mode 0 backdrop. Lower priority wins; lower BG
    // number wins priority ties.
    out = read16(palette, 0);
    int best_priority = 4;

    for (int bg = 3; bg >= 0; --bg) {
        if (!(dispcnt & (1 << (8 + bg))))
            continue;

        const u16 cnt = read16(&gba.read_memory(0x04000008 + bg * 2), 0);
        const u16 hofs = read16(&gba.read_memory(0x04000010 + bg * 4), 0) & 0x1FF;
        const u16 vofs = read16(&gba.read_memory(0x04000012 + bg * 4), 0) & 0x1FF;
        const int priority = cnt & 3;
        if (priority > best_priority)
            continue;

        const int size = cnt >> 14;
        const int width = (size & 1) ? 512 : 256;
        const int height = (size & 2) ? 512 : 256;
        const int bg_x = (x + hofs) & (width - 1);
        const int bg_y = (y + vofs) & (height - 1);
        const int tile_x = bg_x >> 3;
        const int tile_y = bg_y >> 3;
        const int blocks_wide = (size & 1) ? 2 : 1;
        const int block = (tile_y >> 5) * blocks_wide + (tile_x >> 5);
        const u32 map = ((cnt >> 8) & 0x1F) * 0x800 + block * 0x800 +
                        ((tile_y & 31) * 32 + (tile_x & 31)) * 2;
        const u16 entry = read16(vram, map);
        int pixel_x = bg_x & 7;
        int pixel_y = bg_y & 7;
        if (entry & (1 << 10)) pixel_x = 7 - pixel_x;
        if (entry & (1 << 11)) pixel_y = 7 - pixel_y;

        const bool color_256 = cnt & (1 << 7);
        const u32 tile = (cnt & (3 << 2)) * 0x1000 + (entry & 0x3FF) * (color_256 ? 64 : 32);
        const u8 tile_byte = vram[tile + pixel_y * (color_256 ? 8 : 4) + (color_256 ? pixel_x : pixel_x / 2)];
        const u8 index = color_256 ? tile_byte :
            ((pixel_x & 1) ? tile_byte >> 4 : tile_byte & 0x0F);
        if (index == 0)
            continue;

        const u16 palette_index = color_256 ? index : ((entry >> 12) * 16 + index);
        out = read16(palette, palette_index * 2);
        best_priority = priority;
    }

    return true;
}

