    constexpr int width = SCREEN_WIDTH;
    constexpr int height = SCREEN_HEIGHT;
    constexpr int scale = 3;
    constexpr int cycles_per_frame = CYCLES_FRAME;

    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::cerr << "SDL initialization failed: " << SDL_GetError() << "\n";
        return false;
    }

    SDL_Window* window = SDL_CreateWindow(
        "GBA",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        width * scale,
        height * scale,
        0);
    SDL_Renderer* renderer = window
        ? SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED)
        : nullptr;
    SDL_Texture* texture = renderer
        ? SDL_CreateTexture(
              renderer,
              SDL_PIXELFORMAT_ABGR8888,
              SDL_TEXTUREACCESS_STREAMING,
              width,
              height)
        : nullptr;

    if (!window || !renderer || !texture) {
        std::cerr << "SDL display setup failed: " << SDL_GetError() << "\n";
        if (texture)
            SDL_DestroyTexture(texture);
        if (renderer)
            SDL_DestroyRenderer(renderer);
        if (window)
            SDL_DestroyWindow(window);
        SDL_Quit();
        return false;
    }

    bool running = true;

    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT)
                running = false;
        }

        for (int i = 0; i < cycles_per_frame && running; ++i)
            tick();

        SDL_UpdateTexture(texture, nullptr, screen_pixels, width * sizeof(u32));
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, texture, nullptr, nullptr);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyTexture(texture);
    SDL_DestroyRenderer(renderer);
